            if(pc==a("assertion")){if(r(e,1)!=0x80c3446cL&&r(e,1)!=0x80c34480L&&r(e,1)!=0x80c34458L)throw new IllegalStateException("Assertion owner");stopped=new JsonObject();stopped.addProperty("kind","assertion");stopped.addProperty("line",r(e,2));return;}
