            if(!mode.equals("geometry")){put(e,CONTEXT,4,PART);put(e,CONTEXT+6,1,c.get("fast").getAsBoolean()?1:0);put(e,CONTEXT+8,4,c.get("pages_per_block").getAsLong());put(e,CONTEXT+12,4,ps);put(e,CONTEXT+24,4,c.get("base").getAsLong()/ps);put(e,CONTEXT+28,2,c.get("spare").getAsLong());put(e,CONTEXT+30,2,c.get("ecc_total").getAsLong());put(e,CONTEXT+32,2,c.get("ecc_unit").getAsLong());for(int i=0;i<4;i++)put(e,CONTEXT+34+i*2,2,c.getAsJsonArray("positions").get(i).getAsLong());put(e,CONTEXT+52,4,SCRATCH);}
            byte[] part=new byte[92];Arrays.fill(part,60,92,(byte)0xa5);System.arraycopy(new byte[]{112,114,111,98,101},0,part,0,5);System.arraycopy(new byte[]{110,97,110,100},0,part,24,4);e.writeMemory(toAddr(PART),part);put(e,PART+48,4,c.get("base").getAsLong());put(e,PART+52,4,c.get("span").getAsLong());part=mem(e,PART,92);
            byte[] output=new byte[544];Arrays.fill(output,(byte)0xa5);e.writeMemory(toAddr(BUFFER),output);if(mode.equals("pack")||mode.equals("roundtrip")){for(int i=0;i<4;i++)put(e,BUFFER+i,1,c.getAsJsonArray("pack_data").get(i).getAsLong());}byte[] scratch=new byte[8224];for(int i=0;i<8192;i++)scratch[i]=(byte)(i*5+7);Arrays.fill(scratch,8192,8224,(byte)0xa5);e.writeMemory(toAddr(SCRATCH),scratch);e.writeMemory(toAddr(QUERY),(c.get("name_query").getAsString()+"\0").getBytes(java.nio.charset.StandardCharsets.US_ASCII));
            String state=c.get("driver_state").getAsString();e.writeMemory(toAddr(DRIVER),new byte[4]);e.writeMemory(toAddr(OPS),new byte[32]);put(e,DRIVER,4,state.equals("ops_missing")?0:OPS);put(e,OPS+8,4,state.equals("callback_missing")?0:a("page_service"));put(e,OPS+24,4,state.equals("callback_missing")?0:a("chip_query"));put(e,0x80d81f10L,4,state.equals("root_missing")?0:DRIVER);
            e.writeMemory(toAddr(CHIP),new byte[256]);put(e,0x80d81f28L,4,c.get("chip_present").getAsBoolean()?CHIP:0);put(e,CHIP+0x2c,2,3);put(e,CHIP+0x40,4,0x12345678L);put(e,CHIP+0x44,4,0x90abcdefL);for(Object[] f:new Object[][]{{0x54,"pages"},{0x58,"pages_per_block"},{0x5c,"page_size"},{0x60,"spare"}})put(e,CHIP+(int)f[0],4,c.get((String)f[1]).getAsLong());put(e,CHIP+0x97,1,1);put(e,CHIP+0x98,1,2);put(e,CHIP+0x9a,2,c.get("ecc_total").getAsLong());put(e,CHIP+0x9c,2,c.get("ecc_unit").getAsLong());for(int i=0;i<4;i++)put(e,CHIP+0x9e+i*2,2,c.getAsJsonArray("positions").get(i).getAsLong());byte[] chip=mem(e,CHIP,256),ops=mem(e,OPS,32),root=mem(e,DRIVER,4);
            put(e,0x80d81f34L,4,c.getAsJsonArray("seed_dims").get(0).getAsLong());put(e,0x80d81f30L,4,c.getAsJsonArray("seed_dims").get(1).getAsLong());put(e,0x80d81f2cL,4,c.getAsJsonArray("seed_dims").get(2).getAsLong());put(e,0x80d81edcL,1,c.get("registry_ready").getAsBoolean()?1:0);put(e,0x80d81ed8L,4,16);put(e,0x80d81ee0L,4,0x80c33a38L);
            long handle=c.get("null_handle").getAsBoolean()?0:PART;
            if(mode.equals("lookup"))entry(e,a(mode),QUERY);
            else if(mode.equals("ioctl"))entry(e,a(mode),handle,c.get("query").getAsLong(),c.get("null_argument").getAsBoolean()?0:ARG);
            else if(mode.equals("chip_query"))entry(e,a(mode),c.get("query").getAsLong(),ARG,1);
            else if(mode.equals("read"))entry(e,a(mode),handle,c.get("null_output").getAsBoolean()?0:BUFFER,c.get("page").getAsLong(),c.get("column").getAsLong(),c.get("size").getAsLong());
            else if(mode.equals("geometry"))entry(e,a(mode),CONTEXT);
            else if(mode.equals("extract"))entry(e,a(mode),CONTEXT,BUFFER);else if(mode.equals("pack")||mode.equals("roundtrip")){byte[] original=mem(e,BUFFER,512);entry(e,a("pack"),CONTEXT,BUFFER);if(!Arrays.equals(original,mem(e,BUFFER,512)))throw new IllegalStateException("OOB packing input changed");if(stopped==null&&mode.equals("roundtrip")){byte[] empty=new byte[4];Arrays.fill(empty,(byte)0xa5);e.writeMemory(toAddr(BUFFER),empty);entry(e,a("extract"),CONTEXT,BUFFER);}}
